# eliteOS QuickBooks Desktop SDK - ONE test sales order, TEST COMPANY ONLY
#
# Sends the SalesOrderAdd qbXML generated by the shared backend-core builder
# (studioSalesOrderPlan.mjs + studioSalesOrderQbxml.mjs) byte for byte - this script builds no
# order of its own. Reads the order back by TxnID, verifies every accounting field against the
# plan-derived expectations in the spec, then confirms exactly one matching order exists. Running
# the same command again must find the existing order and add nothing (duplicate-retry test).
#
# Scenarios in the spec:
#   A  accepted_sync            - the accepted quote; expected total must equal the accepted total.
#   B  synthetic_tax_scenario   - separately keyed and labeled; never a sync of the acceptance.
#
# Refuses before any SDK call unless:
#   - -ExpectedCompany equals the spec's expectedCompany exactly and ends with " SO TEST";
#   - -CompanyFile is a .QBW whose file name contains "SO TEST" and is not the production file;
#   - neither the name nor the path equals the spec's productionGuard values;
#   - the scenario's qbXML matches its recorded SHA-256, carries the scenario's ExternalGUID and
#     the spec's customer, and its kind/expected totals are consistent (tax never raises an
#     accepted total);
#   - QuickBooks is already running in this Windows session.
# After BeginSession, CompanyName (exact, case-sensitive) and GetCurrentCompanyFileName must both
# match before any other request. Writing additionally needs -Write.
#
# No Brain/HTTP calls, no queue, no lock files, no scheduled-task changes, no CData/ODBC.
# Exit codes: 0 dry run or verified; 2 refused (inputs/gates); 3 SDK or verification failure;
#             4 more than one matching order found.

param(
    [Parameter(Mandatory = $true)][string]$CompanyFile,
    [Parameter(Mandatory = $true)][string]$ExpectedCompany,
    [Parameter(Mandatory = $true)][string]$SpecPath,
    [Parameter(Mandatory = $true)][ValidateSet("A", "B")][string]$Scenario,
    [switch]$Write,
    [string]$OutDir = "C:\eliteOS\logs\qb-so-test"
)

$ErrorActionPreference = "Stop"
$HarnessVersion = "2.0.0-test"
$AppName = "EliteOS QuickBooks SDK Connector"
$AppId = "{A1B2C3D4-E5F6-7890-ABCD-EF1234567890}"
$MaxRequests = 8
$AllowedRequests = @("CompanyQueryRq", "SalesOrderQueryRq", "SalesOrderAddRq")
$ForbiddenPattern = '(?i)<\s*[A-Za-z0-9]*(?:Mod|Del|Void)Rq[\s/>]|TxnDelRq|ListDelRq|TxnVoidRq|iterator\s*='
$Started = Get-Date
$Inv = [Globalization.CultureInfo]::InvariantCulture

function X { param([string]$s) return [System.Security.SecurityElement]::Escape($s) }
function Txt { param($Node, [string]$Path) if ($null -eq $Node) { return $null }; $n = $Node.SelectSingleNode($Path); if ($null -eq $n) { return $null }; return [string]$n.InnerText }
function Money { param($v) if ($null -eq $v -or [string]$v -eq "") { return $null }; return ([decimal]::Parse([string]$v, $Inv)).ToString("0.00", $Inv) }
function FullPath { param([string]$p) try { return [IO.Path]::GetFullPath($p) } catch { return $p } }
function Sha256Hex { param([string]$s) $h = [System.Security.Cryptography.SHA256]::Create(); try { return (($h.ComputeHash([Text.Encoding]::UTF8.GetBytes($s)) | ForEach-Object { $_.ToString("X2") }) -join "") } finally { $h.Dispose() } }
function Norm { param($s) return ([regex]::Replace([string]$s, '\s+', ' ')).Trim().ToLowerInvariant() }

$script:addAllowed = $false
$script:addCount = 0
function Assert-AllowedRequest {
    param([Parameter(Mandatory = $true)][string]$QbXml)
    if ($QbXml -match $ForbiddenPattern) { throw "Refusing request: modify/delete/void or iterator text detected." }
    [xml]$doc = $QbXml
    $msgs = $doc.SelectSingleNode("/QBXML/QBXMLMsgsRq")
    if ($null -eq $msgs) { throw "Refusing request: missing QBXMLMsgsRq." }
    $children = @($msgs.ChildNodes | Where-Object { $_.NodeType -eq [System.Xml.XmlNodeType]::Element })
    if ($children.Count -ne 1) { throw "Refusing request: exactly one request per message is allowed." }
    $rq = $children[0]
    if ($AllowedRequests -notcontains $rq.LocalName) { throw ("Refusing request type {0}." -f $rq.LocalName) }
    if ($rq.LocalName -eq "SalesOrderAddRq") {
        if (-not $script:addAllowed) { throw "Refusing SalesOrderAddRq: writing is not enabled for this run." }
        if ($script:addCount -ge 1) { throw "Refusing a second SalesOrderAddRq in one run." }
    }
    if ($rq.LocalName -eq "SalesOrderQueryRq" -and $null -eq $rq.SelectSingleNode("TxnID") -and $null -eq $rq.SelectSingleNode("MaxReturned")) {
        throw "Refusing unbounded SalesOrderQueryRq: needs TxnID or MaxReturned."
    }
    return $rq.LocalName
}

# Planned ListID wins; FullName only when the plan has no ListID; a planned absent ref must be absent.
function Test-Ref {
    param($Node, [string]$Tag, $Planned)
    $id = Txt $Node "$Tag/ListID"; $name = Txt $Node "$Tag/FullName"
    if ($Planned -and $Planned.listId) { return ($id -ceq [string]$Planned.listId) }
    if ($Planned -and $Planned.fullName) { return ((Norm $name) -eq (Norm $Planned.fullName)) }
    return (-not $id -and -not $name)
}
function Label-Ref { param($Node, [string]$Tag) $id = Txt $Node "$Tag/ListID"; $n = Txt $Node "$Tag/FullName"; if ($n) { return "$n ($id)" }; if ($id) { return $id }; return "(none)" }
function Label-Plan { param($Planned) if (-not $Planned) { return "(none)" }; if ($Planned.fullName) { return ("{0} ({1})" -f $Planned.fullName, $Planned.listId) }; return [string]$Planned.listId }

function Compare-SalesOrder {
    param($Ret, $Exp)
    $m = New-Object System.Collections.Generic.List[string]
    $chk = { param($field, $actual, $expected) if ([string]$actual -cne [string]$expected) { $m.Add(("{0}: QuickBooks '{1}', expected '{2}'" -f $field, $actual, $expected)) } }
    foreach ($pair in @(@("CustomerRef", $Exp.customer), @("ClassRef", $Exp.headerClass), @("TemplateRef", $Exp.template), @("TermsRef", $Exp.terms), @("ItemSalesTaxRef", $Exp.itemSalesTax), @("CustomerSalesTaxCodeRef", $Exp.customerSalesTaxCode))) {
        if (-not (Test-Ref $Ret $pair[0] $pair[1])) { $m.Add(("{0}: QuickBooks {1}, expected {2}" -f $pair[0], (Label-Ref $Ret $pair[0]), (Label-Plan $pair[1]))) }
    }
    if ($Exp.txnDate) { & $chk "TxnDate" (Txt $Ret "TxnDate") $Exp.txnDate }
    & $chk "Memo" (Txt $Ret "Memo") $Exp.memo
    & $chk "ExternalGUID" ([string](Txt $Ret "ExternalGUID")).ToUpperInvariant() ([string]$Exp.externalGuid).ToUpperInvariant()
    & $chk "IsManuallyClosed" (Txt $Ret "IsManuallyClosed") "false"
    & $chk "Subtotal" (Money (Txt $Ret "Subtotal")) $Exp.subtotal
    & $chk "SalesTaxTotal" (Money (Txt $Ret "SalesTaxTotal")) $Exp.salesTaxTotal
    & $chk "TotalAmount" (Money (Txt $Ret "TotalAmount")) $Exp.totalAmount
    if ($Ret.SelectNodes("SalesOrderLineGroupRet").Count) { $m.Add("Unexpected group lines on the order.") }
    $qbLines = @($Ret.SelectNodes("SalesOrderLineRet"))
    $expLines = @($Exp.lines)
    if ($qbLines.Count -ne $expLines.Count) { $m.Add(("Line count: QuickBooks {0}, expected {1}" -f $qbLines.Count, $expLines.Count)) }
    for ($i = 0; $i -lt [Math]::Min($qbLines.Count, $expLines.Count); $i++) {
        $q = $qbLines[$i]; $s = $expLines[$i]; $p = "Line {0}" -f ($i + 1)
        & $chk "$p Desc" (Txt $q "Desc") $s.desc
        if ($s.descriptionOnly) {
            if ((Txt $q "ItemRef/ListID") -or (Txt $q "ItemRef/FullName")) { $m.Add("$p should be description-only but has an item.") }
            $amt = Money (Txt $q "Amount")
            if ($amt -and $amt -ne "0.00") { $m.Add("$p description-only line has amount $amt.") }
            continue
        }
        if (-not (Test-Ref $q "ItemRef" ([pscustomobject]@{ listId = $s.itemListId; fullName = $s.itemName }))) { $m.Add(("{0} ItemRef: QuickBooks {1}, expected {2} ({3})" -f $p, (Label-Ref $q "ItemRef"), $s.itemName, $s.itemListId)) }
        $qty = Txt $q "Quantity"
        & $chk "$p Quantity" $(if ($qty) { ([decimal]::Parse($qty, $Inv)).ToString($Inv) } else { "" }) ([decimal]::Parse([string]$s.quantity, $Inv)).ToString($Inv)
        & $chk "$p Amount" (Money (Txt $q "Amount")) $s.amount
        if (-not (Test-Ref $q "ClassRef" ([pscustomobject]@{ listId = $s.classListId; fullName = $s.className }))) { $m.Add(("{0} ClassRef: QuickBooks {1}, expected {2} ({3})" -f $p, (Label-Ref $q "ClassRef"), $s.className, $s.classListId)) }
        if (-not (Test-Ref $q "SalesTaxCodeRef" ([pscustomobject]@{ listId = $s.salesTaxCodeListId; fullName = $s.salesTaxCodeName }))) { $m.Add(("{0} SalesTaxCodeRef: QuickBooks {1}, expected {2} ({3})" -f $p, (Label-Ref $q "SalesTaxCodeRef"), $s.salesTaxCodeName, $s.salesTaxCodeListId)) }
    }
    return , $m.ToArray()
}

Write-Host ("eliteOS QuickBooks TEST sales order {0} - TEST COMPANY ONLY ({1})" -f $HarnessVersion, $(if ($Write) { "WRITE ENABLED: at most one SalesOrderAdd" } else { "dry run: queries only" }))

# ---- Gates (no SDK yet) --------------------------------------------------------------------------
$refusals = @()
$spec = $null; $sc = $null; $exp = $null
if (-not (Test-Path -LiteralPath $SpecPath -PathType Leaf)) { $refusals += "Spec file not found." }
else { $spec = Get-Content -LiteralPath $SpecPath -Raw -Encoding UTF8 | ConvertFrom-Json }
$CompanyFile = $CompanyFile.Trim(); $ExpectedCompany = $ExpectedCompany.Trim()
if ($spec) {
    $guard = $spec.productionGuard
    if ([int]$spec.specVersion -ne 2) { $refusals += "Spec must be version 2 (generated by the shared builder)." }
    if ($ExpectedCompany -cne [string]$spec.expectedCompany) { $refusals += "-ExpectedCompany must exactly equal the spec expectedCompany." }
    if (-not $ExpectedCompany.EndsWith(" SO TEST", [StringComparison]::Ordinal)) { $refusals += "-ExpectedCompany must end with ' SO TEST'." }
    if (-not $guard -or -not $guard.companyName -or -not $guard.companyFile) { $refusals += "Spec has no productionGuard." }
    elseif ($ExpectedCompany -ieq [string]$guard.companyName) { $refusals += "-ExpectedCompany is the production company name." }
    if ($CompanyFile -notmatch '(?i)\.qbw$') { $refusals += "-CompanyFile must be a .QBW path." }
    elseif (-not (Test-Path -LiteralPath $CompanyFile -PathType Leaf)) { $refusals += "-CompanyFile does not exist." }
    $leaf = Split-Path -Leaf $CompanyFile
    if ($leaf -notmatch 'SO TEST') { $refusals += "-CompanyFile name must contain 'SO TEST'." }
    if ($guard -and ((FullPath $CompanyFile) -ieq (FullPath ([string]$guard.companyFile)) -or $leaf -ieq [string]$guard.companyFileLeaf)) { $refusals += "-CompanyFile is the production company file." }

    $sc = $spec.scenarios.$Scenario
    if (-not $sc) { $refusals += "Spec has no scenario $Scenario." }
    else {
        $exp = $sc.expected
        if ((Sha256Hex ([string]$sc.qbXml)) -ne [string]$sc.qbXmlSha256) { $refusals += "Scenario qbXML does not match its recorded SHA-256 (edited after generation)." }
        try {
            [xml]$addDoc = [string]$sc.qbXml
            $add = $addDoc.SelectSingleNode("/QBXML/QBXMLMsgsRq/SalesOrderAddRq/SalesOrderAdd")
            if ($null -eq $add) { $refusals += "Scenario qbXML is not a single SalesOrderAddRq." }
            else {
                if (([string](Txt $add "ExternalGUID")).ToUpperInvariant() -ne ([string]$sc.externalGuid).ToUpperInvariant()) { $refusals += "Scenario qbXML ExternalGUID differs from the scenario." }
                if ((Txt $add "CustomerRef/ListID") -cne [string]$spec.lookup.customerListId) { $refusals += "Scenario qbXML customer differs from the spec lookup customer." }
                if ((Txt $add "Memo") -cne [string]$exp.memo -or ([string]$exp.memo).IndexOf([string]$sc.memoMarker) -lt 0) { $refusals += "Scenario memo must equal the expected memo and carry the memo marker." }
            }
        } catch { $refusals += "Scenario qbXML is not well-formed XML." }
        if ($sc.planOk -ne $true) { $refusals += "Scenario plan was blocked when generated." }
        if ($sc.kind -eq "accepted_sync") {
            if ($Scenario -ne "A") { $refusals += "Accepted-quote plan must be scenario A." }
            if ([string]$exp.totalAmount -ne [string]$spec.source.acceptedTotal -or [string]$exp.salesTaxTotal -ne "0.00") { $refusals += "Accepted-quote scenario must keep the accepted total with no added tax." }
        } elseif ($sc.kind -eq "synthetic_tax_scenario") {
            if ($sc.syncEligible -ne $false) { $refusals += "Synthetic scenario must not be sync-eligible." }
            if (-not ([string]$exp.memo).StartsWith("SYNTHETIC TAX SCENARIO", [StringComparison]::Ordinal)) { $refusals += "Synthetic scenario memo must be labeled SYNTHETIC TAX SCENARIO." }
        } else { $refusals += ("Unknown scenario kind '{0}'." -f $sc.kind) }
        $sum = 0; foreach ($l in @($exp.lines | Where-Object { -not $_.descriptionOnly })) { $sum += [decimal]::Parse([string]$l.amount, $Inv) }
        if ((Money $sum) -ne [string]$spec.source.acceptedTotal -or (Money $sum) -ne [string]$exp.subtotal) { $refusals += "Scenario lines do not total the accepted amount." }
    }
}
$mySession = [System.Diagnostics.Process]::GetCurrentProcess().SessionId
$qbRunning = $false
try { $qbRunning = [bool]@(Get-CimInstance Win32_Process -Filter "Name LIKE 'QBW%'" | Where-Object { $_.Name -match '^(?i)QBW(32)?\.exe$' -and $_.SessionId -eq $mySession }).Count } catch { }
if (-not $qbRunning) { $refusals += "QuickBooks is not running in this Windows session (open the TEST company first)." }

New-Item -ItemType Directory -Force -Path $OutDir | Out-Null
$report = [ordered]@{
    harnessVersion = $HarnessVersion; ranAt = $Started.ToUniversalTime().ToString("o"); host = $env:COMPUTERNAME
    requested = [ordered]@{ companyFile = $CompanyFile; expectedCompany = $ExpectedCompany; spec = (Split-Path -Leaf $SpecPath); scenario = $Scenario; write = [bool]$Write }
    scenario = $(if ($sc) { [ordered]@{ kind = $sc.kind; label = $sc.label; syncEligible = $sc.syncEligible; externalGuid = $sc.externalGuid; qbXmlSha256 = $sc.qbXmlSha256 } } else { $null })
    refusals = $refusals
    outcome = $null
}
$outFile = Join-Path $OutDir ("sales-order-test-write-{0}-{1}.json" -f $Scenario, (Get-Date -Format "yyyyMMdd-HHmmss"))
if ($refusals.Count) {
    $report.outcome = "REFUSED"
    $report | ConvertTo-Json -Depth 10 | Set-Content -LiteralPath $outFile -Encoding UTF8
    Write-Host "REFUSED (nothing sent to QuickBooks):"; $refusals | ForEach-Object { Write-Host ("  - {0}" -f $_) }
    Write-Host ("Report: {0}" -f $outFile)
    exit 2
}
if ($sc.kind -eq "synthetic_tax_scenario") { Write-Host "SYNTHETIC TAX SCENARIO - not a sync of the accepted quote." }

# ---- SDK session ---------------------------------------------------------------------------------
$QbXmlVersion = [string]$spec.qbXmlVersion
$sdk = [ordered]@{ connectionOpened = $false; sessionOpened = $false; sessionEnded = $false; connectionClosed = $false; requests = 0; stage = "init"; error = $null }
$report.sdk = $sdk
$rp = $null; $ticket = $null; $exitCode = 0
function Send-QbXml {
    param([string]$QbXml)
    if ($sdk.requests -ge $MaxRequests) { throw ("Request cap of {0} reached." -f $MaxRequests) }
    $type = Assert-AllowedRequest -QbXml $QbXml
    if ($type -eq "SalesOrderAddRq") { $script:addCount++ }
    $sdk.requests++
    [xml]$d = [string]$rp.ProcessRequest($ticket, $QbXml)
    $rs = $d.SelectSingleNode("/QBXML/QBXMLMsgsRs/*[1]")
    $code = 0; [void][int]::TryParse([string]$rs.GetAttribute("statusCode"), [ref]$code)
    return [pscustomobject]@{ node = $rs; code = $code; message = [string]$rs.GetAttribute("statusMessage") }
}
function Invoke-Rq {
    param([string]$Inner)
    return Send-QbXml ('<?xml version="1.0" encoding="utf-8"?><?qbxml version="' + (X $QbXmlVersion) + '"?><QBXML><QBXMLMsgsRq onError="stopOnError">' + $Inner + '</QBXMLMsgsRq></QBXML>')
}
function Find-Matches {
    $r = Invoke-Rq ("<SalesOrderQueryRq requestID=""1""><MaxReturned>50</MaxReturned><TxnDateRangeFilter><FromTxnDate>{0}</FromTxnDate><ToTxnDate>{0}</ToTxnDate></TxnDateRangeFilter><EntityFilter><ListID>{1}</ListID></EntityFilter><IncludeLineItems>true</IncludeLineItems></SalesOrderQueryRq>" -f (X $spec.lookup.txnDate), (X $spec.lookup.customerListId))
    if ($r.code -ne 0 -and $r.code -ne 1) { throw ("SalesOrderQueryRq failed: {0} {1}" -f $r.code, $r.message) }
    $all = @($r.node.SelectNodes("SalesOrderRet"))
    if ($all.Count -ge 50) { throw "Lookup returned 50 orders for this customer and date; refusing to decide on a truncated result." }
    $guid = ([string]$sc.externalGuid).ToUpperInvariant()
    return , @($all | Where-Object { ([string](Txt $_ "ExternalGUID")).ToUpperInvariant() -eq $guid -or ([string](Txt $_ "Memo")).IndexOf([string]$sc.memoMarker) -ge 0 })
}
try {
    $sdk.stage = "connect"
    $rp = New-Object -ComObject "QBXMLRP2.RequestProcessor"
    try { $rp.OpenConnection2($AppId, $AppName, 1) } catch { $rp.OpenConnection($AppId, $AppName) }
    $sdk.connectionOpened = $true
    $sdk.stage = "begin_session"
    $ticket = [string]$rp.BeginSession($CompanyFile, 2)
    $sdk.sessionOpened = $true

    $sdk.stage = "identity"
    $openFile = [string]$rp.GetCurrentCompanyFileName($ticket)
    $c = Invoke-Rq '<CompanyQueryRq requestID="1"/>'
    $openName = ([string](Txt $c.node "CompanyRet/CompanyName")).Trim()
    $report.identity = [ordered]@{ companyName = $openName; companyFile = $openFile; nameMatches = ($openName -ceq $ExpectedCompany); fileMatches = ((FullPath $openFile) -ieq (FullPath $CompanyFile)) }
    if (-not ($report.identity.nameMatches -and $report.identity.fileMatches)) { throw "Company identity mismatch; nothing else was sent." }
    if ($openName -ieq [string]$spec.productionGuard.companyName -or (FullPath $openFile) -ieq (FullPath ([string]$spec.productionGuard.companyFile))) { throw "Open company is production; nothing else was sent." }

    $sdk.stage = "pre_lookup"
    $before = Find-Matches
    $report.matchesBefore = $before.Count
    if ($before.Count -gt 1) { $exitCode = 4; throw ("{0} orders already carry this ExternalGUID/memo marker." -f $before.Count) }

    $txnId = $null
    if ($before.Count -eq 1) {
        $txnId = Txt $before[0] "TxnID"
        $report.outcome = "ALREADY_EXISTS_NO_ADD"
    } elseif (-not $Write) {
        $report.outcome = "DRY_RUN_NO_ADD"
        $report.requestPreviewSha256 = $sc.qbXmlSha256
    } else {
        $sdk.stage = "add"
        $script:addAllowed = $true
        try {
            $a = Send-QbXml ([string]$sc.qbXml)
            $report.addStatus = [ordered]@{ code = $a.code; message = $a.message }
            if ($a.code -ne 0) { throw ("SalesOrderAddRq failed: {0} {1}" -f $a.code, $a.message) }
            $txnId = Txt $a.node "SalesOrderRet/TxnID"
        } catch {
            $report.addError = [string]$_.Exception.Message
            $sdk.stage = "lost_ack_lookup"
            $after = Find-Matches
            if ($after.Count -eq 1) { $txnId = Txt $after[0] "TxnID"; $report.addRecoveredByLookup = $true } else { throw }
        } finally { $script:addAllowed = $false }
        $report.outcome = "CREATED"
    }

    if ($txnId) {
        $sdk.stage = "read_back"
        $rb = Invoke-Rq ("<SalesOrderQueryRq requestID=""1""><TxnID>{0}</TxnID><IncludeLineItems>true</IncludeLineItems></SalesOrderQueryRq>" -f (X $txnId))
        $ret = $rb.node.SelectSingleNode("SalesOrderRet")
        if ($null -eq $ret) { throw "Read-back by TxnID returned no order." }
        $report.order = [ordered]@{ txnId = $txnId; refNumber = (Txt $ret "RefNumber"); subtotal = (Money (Txt $ret "Subtotal")); salesTaxTotal = (Money (Txt $ret "SalesTaxTotal")); totalAmount = (Money (Txt $ret "TotalAmount")) }
        $report.mismatches = Compare-SalesOrder -Ret $ret -Exp $exp
        $sdk.stage = "post_count"
        $afterAll = Find-Matches
        $report.matchesAfter = $afterAll.Count
        if ($afterAll.Count -ne 1) { $exitCode = 4; throw ("Expected exactly one matching order after this run; found {0}." -f $afterAll.Count) }
        if (@($report.mismatches).Count) { $exitCode = 3 } else { $report.outcome = $report.outcome + "_VERIFIED" }
    }
    $sdk.stage = "done"
} catch {
    $sdk.error = [string]$_.Exception.Message
    if ($exitCode -eq 0) { $exitCode = 3 }
    if (-not $report.outcome) { $report.outcome = "FAILED" }
} finally {
    if ($ticket) { try { $rp.EndSession($ticket) | Out-Null; $sdk.sessionEnded = $true } catch { } }
    if ($sdk.connectionOpened) { try { $rp.CloseConnection() | Out-Null; $sdk.connectionClosed = $true } catch { } }
    if ($rp) { try { [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($rp) } catch { } }
    $rp = $null
}

$report.elapsedSeconds = [int]((Get-Date) - $Started).TotalSeconds
$report | ConvertTo-Json -Depth 10 | Set-Content -LiteralPath $outFile -Encoding UTF8
Write-Host ("Scenario {0} ({1})  Outcome: {2}  requests: {3}  sessionEnded: {4}  connectionClosed: {5}" -f $Scenario, $sc.kind, $report.outcome, $sdk.requests, $sdk.sessionEnded, $sdk.connectionClosed)
if ($report.identity) { Write-Host ("Company: {0} | {1}" -f $report.identity.companyName, $report.identity.companyFile) }
if ($null -ne $report.matchesBefore) { Write-Host ("Matching orders before: {0}  after: {1}" -f $report.matchesBefore, $(if ($null -ne $report.matchesAfter) { $report.matchesAfter } else { "n/a" })) }
if ($report.order) { Write-Host ("Order TxnID {0} Ref {1}: subtotal {2}, tax {3}, total {4}" -f $report.order.txnId, $report.order.refNumber, $report.order.subtotal, $report.order.salesTaxTotal, $report.order.totalAmount) }
if ($sdk.error) { Write-Host ("Error: {0}" -f $sdk.error) }
if ($report.mismatches -and @($report.mismatches).Count) { Write-Host "Mismatches:"; $report.mismatches | ForEach-Object { Write-Host ("  - {0}" -f $_) } }
Write-Host ("Report: {0}" -f $outFile)
exit $exitCode
